const input = $json.body ?? $json;
const text = (v) => v === null || v === undefined ? '' : String(v).trim();
const bool = (v) => typeof v === 'boolean' ? v : ['true','1','yes','on'].includes(text(v).toLowerCase());

const action = text(input.action || 'list').toLowerCase();
const clinic_name = text(input.clinic_name);
const scope = text(input.scope || 'clinic').toLowerCase();
const template_id = Number(input.template_id ?? 0);
const symptom_category = text(input.symptom_category || 'general').toLowerCase();
const question_code = text(input.question_code);
const question_text_fa = text(input.question_text_fa);
const question_text_en = text(input.question_text_en);
const question_text_ar = text(input.question_text_ar);
const answer_type = text(input.answer_type || 'boolean').toLowerCase();
const required = bool(input.required);
const maps_to_case_field = text(input.maps_to_case_field);
const risk_if_true = text(input.risk_if_true || 'none').toLowerCase();
const sort_order = Number(input.sort_order ?? 100);
const active = bool(input.active);
const confirm_action = bool(input.confirm_action);

let options_json = input.options_json ?? [];
let bulk_items = input.bulk_items ?? [];
try {
  if (typeof options_json === 'string') options_json = JSON.parse(options_json || '[]');
} catch { options_json = null; }
try {
  if (typeof bulk_items === 'string') bulk_items = JSON.parse(bulk_items || '[]');
} catch { bulk_items = null; }

const errors = [];
const actions = ['create','update','activate','deactivate','list','bulk_upsert'];
const answerTypes = ['boolean','number','text','select','multiselect'];

if (!actions.includes(action)) errors.push({field:'action',message:'اقدام معتبر نیست.'});
if (!['clinic','global'].includes(scope)) errors.push({field:'scope',message:'scope معتبر نیست.'});
if (scope === 'clinic' && !clinic_name) errors.push({field:'clinic_name',message:'نام کلینیک الزامی است.'});
if (['update','activate','deactivate'].includes(action) && (!Number.isInteger(template_id) || template_id < 1)) {
  errors.push({field:'template_id',message:'شناسه سؤال الزامی است.'});
}
if (action === 'create' && (!question_code || !question_text_fa)) {
  errors.push({field:'question',message:'کد سؤال و متن فارسی الزامی است.'});
}
if (!answerTypes.includes(answer_type)) errors.push({field:'answer_type',message:'نوع پاسخ معتبر نیست.'});
if (!Array.isArray(options_json)) {
  errors.push({field:'options_json',message:'options_json باید آرایه باشد.'});
  options_json = [];
}
if (['select','multiselect'].includes(answer_type) && options_json.length < 1) {
  errors.push({field:'options_json',message:'برای سؤال انتخابی گزینه لازم است.'});
}
if (!['none','high','urgent'].includes(risk_if_true)) {
  errors.push({field:'risk_if_true',message:'سطح ریسک معتبر نیست.'});
}
if (!Number.isInteger(sort_order) || sort_order < 0 || sort_order > 100000) {
  errors.push({field:'sort_order',message:'ترتیب نمایش معتبر نیست.'});
}
if (action === 'bulk_upsert' && (!Array.isArray(bulk_items) || bulk_items.length < 1 || bulk_items.length > 500)) {
  errors.push({field:'bulk_items',message:'bulk_items باید آرایه‌ای با 1 تا 500 سؤال باشد.'});
}
if (!Array.isArray(bulk_items)) bulk_items = [];
if (action !== 'list' && confirm_action !== true) {
  errors.push({field:'confirm_action',message:'تغییر باید تأیید شود.'});
}

return [{json:{
  action, clinic_name, scope, template_id, symptom_category, question_code,
  question_text_fa, question_text_en, question_text_ar, answer_type,
  options_json_text: JSON.stringify(options_json), required, maps_to_case_field,
  risk_if_true, sort_order, active, bulk_items_json: JSON.stringify(bulk_items),
  validation_status: errors.length ? 'invalid' : 'valid', errors
}}];
